function bit(bytes,p){return(bytes[(p-1)>>>3]>>>(7-((p-1)&7)))&1}
function schedule(key){let bits=PC1.map(p=>bit(key,p)),c=bits.slice(0,28),d=bits.slice(28);return SHIFTS.map(n=>{c=c.slice(n).concat(c.slice(0,n));d=d.slice(n).concat(d.slice(0,n));bits=c.concat(d);const k=[];for(let g=0;g<8;g++){let v=0;for(let j=0;j<6;j++)v=(v<<1)|bits[PC2[g*6+j]-1];k.push(v)}return k})}
const SP=S.map((table,g)=>Array.from({length:64},(_,x)=>{const row=((x&32)>>>4)|(x&1),col=(x>>>1)&15;const raw=table[row*16+col]<<(28-4*g);let v=0;for(let i=0;i<32;i++)v=(v<<1)|((raw>>>(32-P[i]))&1);return v}));
function transform(block,keys){let l=0,r=0;for(let i=0;i<32;i++){l=(l<<1)|bit(block,IP[i]);r=(r<<1)|bit(block,IP[i+32])}for(const k of keys){let f=0;for(let g=0;g<8;g++){let x=0;for(let j=0;j<6;j++)x=(x<<1)|((r>>>(32-E[g*6+j]))&1);f^=SP[g][x^k[g]]}const t=r;r=l^f;l=t}const out=new Uint8Array(8);for(let i=0;i<64;i++){const p=FP[i];const b=p<=32?(r>>>(32-p))&1:(l>>>(64-p))&1;out[i>>>3]|=b<<(7-(i&7))}return out}
export function desBlock(block,key,decrypt=false){if(block.length!==8||key.length!==8)throw Error('DES blocks and keys must be 8 bytes.');const keys=schedule(key);return transform(block,decrypt?keys.reverse():keys)}
export function parseKey(value,format='text'){if(format==='hex'){if(!/^[0-9a-fA-F]{16}$/.test(value))throw Error('Enter exactly 16 hexadecimal digits for the DES key.');return Uint8Array.from(value.match(/../g),v=>parseInt(v,16))}if(format!=='text'||! /^[\x20-\x7e]{8}$/.test(value))throw Error('Enter exactly 8 printable ASCII characters for the DES key.');return enc.encode(value)}
export function base64(bytes){let s='';for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(s)}
export function unbase64(s){if(s.length>LIMIT*1.5)throw Error('Encrypted note is too large.');try{return Uint8Array.from(atob(s.trim()),c=>c.charCodeAt(0))}catch{throw Error('Paste a valid Base64 encrypted note.')}}
export async function cbc(data,key,iv,decrypt=false,onProgress=()=>{}){if(key.length!==8||iv.length!==8)throw Error('Invalid DES key or IV.');if(decrypt&&(!data.length||data.length%8))throw Error('Invalid DES ciphertext length.');const keys=schedule(key);if(decrypt)keys.reverse();let input=data;if(!decrypt){const n=8-data.length%8;input=new Uint8Array(data.length+n);input.set(data);input.fill(n,data.length)}const output=new Uint8Array(input.length);let previous=iv;for(let offset=0;offset<input.length;offset+=8){const block=input.slice(offset,offset+8);let transformed;if(decrypt){transformed=transform(block,keys);for(let i=0;i<8;i++)transformed[i]^=previous[i];previous=block}else{for(let i=0;i<8;i++)block[i]^=previous[i];transformed=transform(block,keys);previous=transformed}output.set(transformed,offset);if(offset%32768===0){onProgress(Math.floor(offset/input.length*100));await new Promise(resolve=>setTimeout(resolve,0))}}onProgress(100);if(decrypt){const n=output.at(-1);if(n<1||n>8||!output.slice(-n).every(b=>b===n))throw Error('Could not decrypt. Check the key; the content may be damaged.');return output.slice(0,-n)}return output}
const MAGIC=enc.encode('CVDES001');
export async function seal(data,key,metadata,onProgress){if(data.length>LIMIT)throw Error('Maximum file size is 20 MB.');const meta=enc.encode(JSON.stringify(metadata));if(meta.length>16384)throw Error('File name is too long.');const plain=new Uint8Array(4+meta.length+data.length);new DataView(plain.buffer).setUint32(0,meta.length);plain.set(meta,4);plain.set(data,4+meta.length);const iv=crypto.getRandomValues(new Uint8Array(8)),cipher=await cbc(plain,key,iv,false,onProgress);const result=new Uint8Array(16+cipher.length);result.set(MAGIC);result.set(iv,8);result.set(cipher,16);return result}
export async function open(bytes,key,onProgress){if(bytes.length<24||bytes.length>LIMIT+65536||!MAGIC.every((v,i)=>bytes[i]===v))throw Error('Use a DES file or note created with this app. Earlier AES files are not supported.');const plain=await cbc(bytes.slice(16),key,bytes.slice(8,16),true,onProgress);try{if(plain.length<4)throw Error();const n=new DataView(plain.buffer).getUint32(0);if(n>16384||n+4>plain.length)throw Error();const metadata=JSON.parse(dec.decode(plain.slice(4,4+n)));if(!['note','file'].includes(metadata.kind)||typeof metadata.name!=='string')throw Error();return{data:plain.slice(4+n),metadata}}catch{throw Error('Could not decrypt. Check the key; the content may be damaged.')}}
